import { z } from "zod";

export const gatewayModels = ["gpt-image-2", "gemini-3.1-flash-image"] as const;
export const imageGateways = ["cloudflare", "vercel"] as const;
export const authModes = ["byok", "stored-byok", "unified-billing"] as const;
export const imageMediaTypes = [
  "image/jpeg",
  "image/png",
  "image/webp",
] as const;
// Leave room for multipart fields under Vercel's 4.5 MB request limit.
export const maximumReferenceBytes = 3 * 1024 * 1024;
export const maximumReferences = 4;
export const gatewayRequestSchema = z.object({
  model: z.enum(gatewayModels),
  prompt: z.string().trim().min(1).max(5000),
  quality: z.enum(["low", "medium", "high"]).default("low"),
  size: z.enum(["1024x1024", "1024x1536", "1536x1024"]).default("1024x1024"),
  imageSize: z.enum(["1K", "2K", "4K"]).default("1K"),
  aspectRatio: z.enum(["1:1", "2:3", "3:2", "9:16", "16:9"]).default("1:1"),
});
export type GatewayRequest = z.input<typeof gatewayRequestSchema> & {
  references?: { bytes: Uint8Array; mediaType: string }[];
};
export interface GatewaySetup {
  authMode: (typeof authModes)[number] | "gateway-managed";
  gateway: (typeof imageGateways)[number];
  missing: string[];
  models: {
    id: (typeof gatewayModels)[number];
    available: boolean;
    missing: string[];
  }[];
}
export interface CostLookup {
  customCost: boolean | null;
  estimateUsd: number | null;
  httpStatus: number | null;
  isByok: boolean | null;
  log: {
    id: string;
    model: string;
    provider: string;
    cached?: boolean;
    duration?: number;
    tokens_in?: number;
    tokens_out?: number;
    success?: boolean;
  } | null;
  reportedUsd: number | null;
  source: "cloudflare-log" | "vercel-generation";
  status:
    | "not-configured"
    | "missing-request-id"
    | "available"
    | "pending"
    | "failed";
}
export interface GatewayReceipt {
  actualCostUsd: null;
  cacheStatus: string | null;
  costLookup: CostLookup;
  credentialMode: GatewaySetup["authMode"];
  eventId: string | null;
  gateway: (typeof imageGateways)[number];
  gatewayRequestId: string | null;
  httpStatus: number | null;
  provider: "openai" | "google";
  providerRequestId: string | null;
  providerResponseId: string | null;
  requestedModel: (typeof gatewayModels)[number];
  servedModel: string | null;
  usage: {
    inputTokens: number | null;
    outputTokens: number | null;
    totalTokens: number | null;
  };
}
export interface GatewayResult {
  images: { base64: string; mediaType: string }[];
  receipt: GatewayReceipt;
}

import type { authModes, GatewayRequest, GatewayResult } from "../contract";

export interface CloudflareConfig {
  accountId: string;
  apiToken?: string;
  authMode: (typeof authModes)[number];
  byokAlias?: string;
  gateway: "cloudflare";
  gatewayId: string;
  gatewayToken: string;
  googleKey?: string;
  openaiKey?: string;
}

export type ImageGeneratorConfig =
  | CloudflareConfig
  | { gateway: "vercel"; apiKey: string };

// One image request, no persistence or credit effects. Provider failures throw
// GatewayGenerationError with a receipt. No application retry or gateway fallback.
export type ImageGenerator = (
  request: GatewayRequest
) => Promise<GatewayResult>;

import "server-only";
import {
  type GatewayRequest,
  type GatewaySetup,
  gatewayModels,
} from "../contract";
import type { ImageGeneratorConfig } from "./config";
import { env } from "./env-source";

export function getGatewaySetup(): GatewaySetup {
  if (env.IMAGE_GATEWAY === "vercel") {
    const missing = env.AI_GATEWAY_API_KEY ? [] : ["AI_GATEWAY_API_KEY"];
    return {
      gateway: "vercel",
      authMode: "gateway-managed",
      missing,
      models: gatewayModels.map((id) => ({
        id,
        available: missing.length === 0,
        missing,
      })),
    };
  }
  const required = [
    "CLOUDFLARE_ACCOUNT_ID",
    "CLOUDFLARE_AI_GATEWAY_ID",
    "CLOUDFLARE_AI_GATEWAY_TOKEN",
  ] as const;
  const missing = required.filter((key) => !env[key]);
  const authMode = env.CLOUDFLARE_AI_GATEWAY_AUTH_MODE;
  const models = gatewayModels.map((id) => {
    const key =
      id === "gpt-image-2"
        ? "CLOUDFLARE_OPENAI_API_KEY"
        : "CLOUDFLARE_GOOGLE_API_KEY";
    const modelMissing = [
      ...missing,
      ...(authMode === "byok" && !env[key] ? [key] : []),
    ];
    return { id, available: modelMissing.length === 0, missing: modelMissing };
  });
  return { gateway: "cloudflare", authMode, missing, models };
}

export function getImageGeneratorConfig(
  model: GatewayRequest["model"]
): ImageGeneratorConfig {
  if (env.IMAGE_GATEWAY === "vercel") {
    if (!env.AI_GATEWAY_API_KEY) {
      throw new Error("Configure AI_GATEWAY_API_KEY on the server.");
    }
    return { gateway: "vercel", apiKey: env.AI_GATEWAY_API_KEY };
  }
  const setup = getGatewaySetup().models.find((entry) => entry.id === model);
  const accountId = env.CLOUDFLARE_ACCOUNT_ID;
  const gatewayId = env.CLOUDFLARE_AI_GATEWAY_ID;
  const gatewayToken = env.CLOUDFLARE_AI_GATEWAY_TOKEN;
  if (!(setup?.available && accountId && gatewayId && gatewayToken)) {
    throw new Error(`Configure ${setup?.missing.join(", ")} on the server.`);
  }
  return {
    gateway: "cloudflare",
    accountId,
    gatewayId,
    gatewayToken,
    authMode: env.CLOUDFLARE_AI_GATEWAY_AUTH_MODE,
    byokAlias: env.CLOUDFLARE_AI_GATEWAY_BYOK_ALIAS,
    openaiKey: env.CLOUDFLARE_OPENAI_API_KEY,
    googleKey: env.CLOUDFLARE_GOOGLE_API_KEY,
    apiToken: env.CLOUDFLARE_API_TOKEN,
  };
}

import { z } from "zod";
import { authModes, imageGateways } from "../contract";

function getGatewayAppEnv() {
  // biome-ignore lint/style/noProcessEnv: Consumer apps supply their own server environment.
  return process.env;
}

const source = getGatewayAppEnv();
const gateway = z
  .enum(imageGateways)
  .default("cloudflare")
  .parse(source.IMAGE_GATEWAY || undefined);
export const env = {
  IMAGE_GATEWAY: gateway,
  AI_GATEWAY_API_KEY: source.AI_GATEWAY_API_KEY || undefined,
  CLOUDFLARE_ACCOUNT_ID: source.CLOUDFLARE_ACCOUNT_ID || undefined,
  CLOUDFLARE_AI_GATEWAY_ID: source.CLOUDFLARE_AI_GATEWAY_ID || undefined,
  CLOUDFLARE_AI_GATEWAY_TOKEN: source.CLOUDFLARE_AI_GATEWAY_TOKEN || undefined,
  CLOUDFLARE_AI_GATEWAY_AUTH_MODE: z
    .enum(authModes)
    .default("byok")
    .parse(
      gateway === "cloudflare"
        ? source.CLOUDFLARE_AI_GATEWAY_AUTH_MODE || undefined
        : undefined
    ),
  CLOUDFLARE_AI_GATEWAY_BYOK_ALIAS:
    source.CLOUDFLARE_AI_GATEWAY_BYOK_ALIAS || undefined,
  CLOUDFLARE_OPENAI_API_KEY: source.CLOUDFLARE_OPENAI_API_KEY || undefined,
  CLOUDFLARE_GOOGLE_API_KEY: source.CLOUDFLARE_GOOGLE_API_KEY || undefined,
  CLOUDFLARE_API_TOKEN: source.CLOUDFLARE_API_TOKEN || undefined,
};

import { z } from "zod";
import type { CostLookup, GatewayReceipt } from "../contract";
import type { CloudflareConfig } from "./config";

const logSchema = z.object({
  success: z.literal(true),
  result: z.object({
    id: z.string(),
    model: z.string(),
    provider: z.string(),
    cost: z.number().finite().nonnegative().nullish(),
    custom_cost: z.boolean().nullish(),
    cached: z.boolean().optional(),
    duration: z.number().optional(),
    tokens_in: z.number().optional(),
    tokens_out: z.number().optional(),
    success: z.boolean().optional(),
  }),
});

export function emptyCostLookup(
  status: CostLookup["status"],
  source: CostLookup["source"] = "cloudflare-log"
): CostLookup {
  return {
    status,
    source,
    estimateUsd: null,
    reportedUsd: null,
    isByok: null,
    customCost: null,
    httpStatus: null,
    log: null,
  };
}

export function captureResponse(receipt: GatewayReceipt, response: Response) {
  receipt.httpStatus = response.status;
  receipt.gatewayRequestId = response.headers.get("cf-aig-log-id");
  receipt.eventId = response.headers.get("cf-aig-event-id");
  receipt.cacheStatus = response.headers.get("cf-aig-cache-status");
  receipt.providerRequestId = response.headers.get("x-request-id");
}

export async function lookupGatewayCost(
  config: CloudflareConfig,
  logId: string | null,
  transport: typeof fetch = fetch
): Promise<CostLookup> {
  if (!config.apiToken) {
    return emptyCostLookup("not-configured");
  }
  if (!logId) {
    return emptyCostLookup("missing-request-id");
  }
  let httpStatus: number | null = null;
  try {
    const response = await transport(
      `https://api.cloudflare.com/client/v4/accounts/${encodeURIComponent(config.accountId)}/ai-gateway/gateways/${encodeURIComponent(config.gatewayId)}/logs/${encodeURIComponent(logId)}`,
      {
        headers: { Authorization: `Bearer ${config.apiToken}` },
        signal: AbortSignal.timeout(5000),
      }
    );
    httpStatus = response.status;
    if (!response.ok) {
      return {
        ...emptyCostLookup(response.status === 404 ? "pending" : "failed"),
        httpStatus,
      };
    }
    const { result } = logSchema.parse(await response.json());
    const { cost, custom_cost: customCost, ...log } = result;
    return {
      status: "available",
      source: "cloudflare-log",
      estimateUsd: cost ?? null,
      reportedUsd: null,
      isByok: null,
      customCost: customCost ?? null,
      httpStatus,
      log,
    };
  } catch {
    // An observable cost lookup failure must not discard a completed image.
    return { ...emptyCostLookup("failed"), httpStatus };
  }
}

import { createGoogleGenerativeAI } from "@ai-sdk/google";
import { createOpenAI } from "@ai-sdk/openai";
import { createGateway, generateImage, generateText, wrapImageModel } from "ai";
import { z } from "zod";
import {
  type CostLookup,
  type GatewayReceipt,
  type GatewayResult,
  gatewayRequestSchema,
} from "../contract";
import type {
  CloudflareConfig,
  ImageGenerator,
  ImageGeneratorConfig,
} from "./config";
import { captureResponse, emptyCostLookup, lookupGatewayCost } from "./receipt";

export type { ImageGenerator, ImageGeneratorConfig } from "./config";

export class GatewayGenerationError extends Error {
  readonly receipt: GatewayReceipt;
  constructor(message: string, receipt: GatewayReceipt, cause?: unknown) {
    super(message, { cause });
    this.name = "GatewayGenerationError";
    this.receipt = receipt;
  }
}

function recordUsage(
  receipt: GatewayReceipt,
  usage: { inputTokens?: number; outputTokens?: number; totalTokens?: number }
) {
  receipt.usage = {
    inputTokens: usage.inputTokens ?? null,
    outputTokens: usage.outputTokens ?? null,
    totalTokens: usage.totalTokens ?? null,
  };
}

function cloudflareAdapter(
  config: CloudflareConfig,
  receipt: GatewayReceipt,
  transport: typeof fetch
) {
  const providerKey =
    receipt.provider === "openai" ? config.openaiKey : config.googleKey;
  if (config.authMode === "byok" && !providerKey) {
    throw new Error(`Missing ${receipt.provider} BYOK key.`);
  }
  const headers = {
    "cf-aig-authorization": `Bearer ${config.gatewayToken}`,
    "cf-aig-skip-cache": "true",
    "cf-aig-max-attempts": "1",
    "cf-aig-collect-log": "true",
    "cf-aig-collect-log-payload": "false",
    ...(config.authMode === "unified-billing"
      ? {}
      : { "cf-aig-no-wholesale": "true" }),
    ...(config.authMode === "stored-byok" && config.byokAlias
      ? { "cf-aig-byok-alias": config.byokAlias }
      : {}),
  };
  // Official providers require an apiKey. Strip their placeholder before
  // Cloudflare resolves stored keys or billing.
  const gatewayFetch: typeof fetch = async (url, init) => {
    const requestHeaders = new Headers(init?.headers);
    if (config.authMode !== "byok") {
      requestHeaders.delete("authorization");
      requestHeaders.delete("x-goog-api-key");
    }
    const response = await transport(url, { ...init, headers: requestHeaders });
    captureResponse(receipt, response);
    return response;
  };
  const baseURL = `https://gateway.ai.cloudflare.com/v1/${encodeURIComponent(config.accountId)}/${encodeURIComponent(config.gatewayId)}`;
  const openai = createOpenAI({
    baseURL: `${baseURL}/openai`,
    apiKey: providerKey ?? "unused",
    headers,
    fetch: gatewayFetch,
  });
  const google = createGoogleGenerativeAI({
    baseURL: `${baseURL}/google-ai-studio/v1beta`,
    apiKey: providerKey ?? "unused",
    headers,
    fetch: gatewayFetch,
  });
  return {
    imageModel: openai.image("gpt-image-2"),
    languageModel: google("gemini-3.1-flash-image"),
    providerOptions: {},
    captureResult(_metadata: unknown, body?: unknown) {
      if (receipt.requestedModel !== "gemini-3.1-flash-image") {
        return;
      }
      // SDK-synthesized model/id values cannot establish upstream identity.
      const metadata = z
        .object({
          modelVersion: z.string().optional(),
          responseId: z.string().optional(),
        })
        .parse(body);
      receipt.servedModel = metadata.modelVersion ?? null;
      receipt.providerResponseId = metadata.responseId ?? null;
    },
    captureError(_cause: unknown) {
      // Cloudflare error correlation is captured from HTTP headers above.
    },
    lookupCost: () =>
      lookupGatewayCost(config, receipt.gatewayRequestId, transport),
  };
}

function vercelAdapter(
  config: Extract<ImageGeneratorConfig, { gateway: "vercel" }>,
  receipt: GatewayReceipt,
  transport: typeof fetch
) {
  let lookupStatus: number | null = null;
  const gateway = createGateway({
    apiKey: config.apiKey,
    fetch: async (url, init) => {
      const isLookup = new URL(String(url)).pathname === "/v1/generation";
      const response = await transport(url, {
        ...init,
        ...(isLookup ? { signal: AbortSignal.timeout(5000) } : {}),
      });
      if (isLookup) {
        lookupStatus = response.status;
      } else {
        receipt.httpStatus = response.status;
      }
      return response;
    },
  });
  function captureResult(metadata: unknown) {
    const parsed = z
      .object({
        gateway: z.object({ generationId: z.string().optional() }).optional(),
      })
      .safeParse(metadata);
    receipt.gatewayRequestId = parsed.success
      ? (parsed.data.gateway?.generationId ?? null)
      : null;
  }
  return {
    imageModel: wrapImageModel({
      model: gateway.image("openai/gpt-image-2"),
      middleware: {
        specificationVersion: "v3",
        async wrapGenerate({ doGenerate }) {
          const result = await doGenerate();
          // generateImage discards provider metadata when it rejects an empty result.
          captureResult(result.providerMetadata);
          return result;
        },
      },
    }),
    languageModel: gateway("google/gemini-3.1-flash-image"),
    providerOptions: {
      gateway: { only: [receipt.provider] },
    },
    captureResult,
    captureError(cause: unknown) {
      // AI SDK may wrap a gateway error. Keep the gateway's generation ID.
      const visited = new Set<unknown>();
      let current = cause;
      while (current && typeof current === "object" && !visited.has(current)) {
        visited.add(current);
        if (
          "generationId" in current &&
          typeof current.generationId === "string"
        ) {
          receipt.gatewayRequestId = current.generationId;
          return;
        }
        current = "cause" in current ? current.cause : null;
      }
    },
    async lookupCost(): Promise<CostLookup> {
      const empty = (status: CostLookup["status"]) =>
        emptyCostLookup(status, "vercel-generation");
      if (!receipt.gatewayRequestId) {
        return empty("missing-request-id");
      }
      try {
        const info = await gateway.getGenerationInfo({
          id: receipt.gatewayRequestId,
        });
        return {
          ...empty("available"),
          httpStatus: lookupStatus,
          reportedUsd: z.number().finite().nonnegative().parse(info.totalCost),
          isByok: info.isByok,
          log: { id: info.id, model: info.model, provider: info.providerName },
        };
      } catch {
        return {
          ...empty(lookupStatus === 404 ? "pending" : "failed"),
          httpStatus: lookupStatus,
        };
      }
    },
  };
}

/** Select once at the composition point; callers share this Seam across gateways. */
export function createImageGenerator(
  config: ImageGeneratorConfig,
  dependencies: { fetch?: typeof fetch } = {}
): ImageGenerator {
  const transport = dependencies.fetch ?? fetch;
  return async (input) => {
    const request = gatewayRequestSchema.parse(input);
    const receipt: GatewayReceipt = {
      gateway: config.gateway,
      gatewayRequestId: null,
      provider: request.model === "gpt-image-2" ? "openai" : "google",
      requestedModel: request.model,
      credentialMode:
        config.gateway === "cloudflare" ? config.authMode : "gateway-managed",
      eventId: null,
      providerRequestId: null,
      providerResponseId: null,
      servedModel: null,
      httpStatus: null,
      cacheStatus: null,
      usage: { inputTokens: null, outputTokens: null, totalTokens: null },
      actualCostUsd: null,
      costLookup: emptyCostLookup(
        "not-configured",
        config.gateway === "cloudflare" ? "cloudflare-log" : "vercel-generation"
      ),
    };
    const adapter =
      config.gateway === "cloudflare"
        ? cloudflareAdapter(config, receipt, transport)
        : vercelAdapter(config, receipt, transport);
    const abortSignal = AbortSignal.timeout(120_000);
    let images: GatewayResult["images"];
    try {
      if (request.model === "gpt-image-2") {
        const result = await generateImage({
          model: adapter.imageModel,
          n: 1,
          maxRetries: 0,
          abortSignal,
          size: request.size,
          prompt: input.references?.length
            ? {
                text: request.prompt,
                images: input.references.map((image) => image.bytes),
              }
            : request.prompt,
          providerOptions: {
            ...adapter.providerOptions,
            openai: { quality: request.quality, outputFormat: "jpeg" },
          },
        });
        images = result.images.map((image) => ({
          base64: image.base64,
          mediaType: image.mediaType,
        }));
        adapter.captureResult(result.providerMetadata);
        recordUsage(receipt, result.usage);
      } else {
        const result = await generateText({
          model: adapter.languageModel,
          maxRetries: 0,
          abortSignal,
          messages: [
            {
              role: "user",
              content: [
                { type: "text", text: request.prompt },
                ...(input.references ?? []).map((image) => ({
                  type: "image" as const,
                  image: image.bytes,
                  mediaType: image.mediaType,
                })),
              ],
            },
          ],
          providerOptions: {
            ...adapter.providerOptions,
            google: {
              responseModalities: ["IMAGE"],
              imageConfig: {
                imageSize: request.imageSize,
                aspectRatio: request.aspectRatio,
              },
            },
          },
        });
        images = result.files
          .filter((file) => file.mediaType.startsWith("image/"))
          .map((image) => ({
            base64: image.base64,
            mediaType: image.mediaType,
          }));
        adapter.captureResult(result.providerMetadata, result.response.body);
        recordUsage(receipt, result.usage);
      }
    } catch (cause) {
      adapter.captureError(cause);
      receipt.costLookup = await adapter.lookupCost();
      throw new GatewayGenerationError(
        `${config.gateway} ${receipt.provider} generation failed${receipt.httpStatus ? ` (HTTP ${receipt.httpStatus})` : " before a valid model response"}.`,
        receipt,
        cause
      );
    }
    receipt.costLookup = await adapter.lookupCost();
    if (images.length === 0) {
      throw new GatewayGenerationError("The model returned no image.", receipt);
    }
    return { images, receipt };
  };
}

import "server-only";
import { ZodError } from "zod";
import {
  gatewayRequestSchema,
  imageMediaTypes,
  maximumReferenceBytes,
  maximumReferences,
} from "../contract";
import { getGatewaySetup, getImageGeneratorConfig } from "./env";
import { createImageGenerator, GatewayGenerationError } from "./generate";

const responseHeaders = { "Cache-Control": "no-store" };

export async function handleGatewayImageRequest(
  request: Request
): Promise<Response> {
  let form: FormData;
  try {
    form = await request.formData();
  } catch {
    return Response.json(
      { error: "Send multipart form data with model and prompt." },
      { status: 400, headers: responseHeaders }
    );
  }
  const parsed = gatewayRequestSchema.safeParse(Object.fromEntries(form));
  if (!parsed.success) {
    return Response.json(
      {
        error: parsed.error.issues
          .map((issue) => `${issue.path.join(".")}: ${issue.message}`)
          .join("; "),
      },
      { status: 400, headers: responseHeaders }
    );
  }
  const files = form
    .getAll("reference")
    .filter((value): value is File => value instanceof File && value.size > 0);
  if (
    files.length > maximumReferences ||
    files.reduce((total, file) => total + file.size, 0) >
      maximumReferenceBytes ||
    files.some(
      (file) =>
        !imageMediaTypes.includes(file.type as (typeof imageMediaTypes)[number])
    )
  ) {
    return Response.json(
      {
        error: "Use up to 4 PNG, JPEG or WebP references, at most 3 MB total.",
      },
      { status: 400, headers: responseHeaders }
    );
  }
  const setup = getGatewaySetup().models.find(
    (model) => model.id === parsed.data.model
  );
  if (!setup) {
    throw new Error("Missing model setup.");
  }
  if (!setup.available) {
    return Response.json(
      { error: `Configure ${setup.missing.join(", ")} on the server.` },
      { status: 503, headers: responseHeaders }
    );
  }
  try {
    const references = await Promise.all(
      files.map(async (file) => ({
        bytes: new Uint8Array(await file.arrayBuffer()),
        mediaType: file.type,
      }))
    );
    const generate = createImageGenerator(
      getImageGeneratorConfig(parsed.data.model)
    );
    const result = await generate({ ...parsed.data, references });
    return Response.json(result, { headers: responseHeaders });
  } catch (error) {
    if (error instanceof GatewayGenerationError) {
      return Response.json(
        { error: error.message, receipt: error.receipt },
        { status: 502, headers: responseHeaders }
      );
    }
    if (error instanceof ZodError) {
      return Response.json(
        { error: "Invalid generation configuration." },
        { status: 400, headers: responseHeaders }
      );
    }
    throw error;
  }
}

import { DemoWorkspaceShell } from "@/components/demo-workspace-shell";
import { getGatewaySetup } from "@/lib/cloudflare-ai-gateway/server/env";
import { GatewayWorkspace } from "./gateway-workspace";

export function GatewayScreen() {
  const setup = getGatewaySetup();
  return (
    <DemoWorkspaceShell
      badges={[setup.gateway, setup.authMode]}
      breadcrumbTitle="Cloudflare AI Gateway"
      summary="Create and edit images with GPT Image 2 or Gemini 3.1 Flash Image through your selected gateway."
      title="Image gateway migration"
    >
      <GatewayWorkspace setup={setup} />
    </DemoWorkspaceShell>
  );
}

"use client";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import Image from "next/image";
import type { GatewaySetup } from "@/lib/cloudflare-ai-gateway/contract";
import { GatewayResults } from "./gateway-results";
import { useGatewayWorkspace } from "./use-gateway-workspace";

const selectClassName =
  "h-9 w-full border border-input bg-background px-3 text-sm outline-none focus-visible:ring-2 focus-visible:ring-ring";

export function GatewayWorkspace({ setup }: { setup: GatewaySetup }) {
  const state = useGatewayWorkspace(setup);
  return (
    <div className="grid h-full min-h-0 gap-6 lg:grid-cols-[minmax(18rem,24rem)_minmax(0,1fr)]">
      <form
        className="flex min-h-0 flex-col gap-5 overflow-y-auto border border-border bg-card p-5"
        onSubmit={state.generate}
